(CASE WHEN EXISTS (SELECT 1 FROM frozen_novels f WHERE f.novel_id = n.id) OR EXISTS (SELECT 1 FROM novel_tags t WHERE t.novel_id = n.id AND t.tag_fold = 'frozen') THEN '凍結' ELSE '' END || CASE WHEN (EXISTS (SELECT 1 FROM frozen_novels f WHERE f.novel_id = n.id) OR EXISTS (SELECT 1 FROM novel_tags t WHERE t.novel_id = n.id AND t.tag_fold = 'frozen')) AND (n.end <> 0 OR EXISTS (SELECT 1 FROM novel_tags t WHERE t.novel_id = n.id AND t.tag = 'end')) THEN ', ' ELSE '' END || CASE WHEN n.end <> 0 OR EXISTS (SELECT 1 FROM novel_tags t WHERE t.novel_id = n.id AND t.tag = 'end') THEN '完結' ELSE '' END || CASE WHEN (EXISTS (SELECT 1 FROM frozen_novels f WHERE f.novel_id = n.id) OR EXISTS (SELECT 1 FROM novel_tags t WHERE t.novel_id = n.id AND t.tag_fold = 'frozen') OR n.end <> 0 OR EXISTS (SELECT 1 FROM novel_tags t WHERE t.novel_id = n.id AND t.tag = 'end')) AND EXISTS (SELECT 1 FROM novel_tags t WHERE t.novel_id = n.id AND t.tag = '404') THEN ', ' ELSE '' END || CASE WHEN EXISTS (SELECT 1 FROM novel_tags t WHERE t.novel_id = n.id AND t.tag = '404') THEN '削除' ELSE '' END || CASE WHEN (EXISTS (SELECT 1 FROM frozen_novels f WHERE f.novel_id = n.id) OR EXISTS (SELECT 1 FROM novel_tags t WHERE t.novel_id = n.id AND t.tag_fold = 'frozen') OR n.end <> 0 OR EXISTS (SELECT 1 FROM novel_tags t WHERE t.novel_id = n.id AND t.tag = 'end') OR EXISTS (SELECT 1 FROM novel_tags t WHERE t.novel_id = n.id AND t.tag = '404')) AND n.suspend <> 0 THEN ', ' ELSE '' END || CASE WHEN n.suspend <> 0 THEN '中断' ELSE '' END)
